import React, { useState, useEffect, useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { 
    FiTrendingUp, FiCheckCircle, FiClock, FiFileText, FiMapPin, 
    FiArrowLeft, FiMenu, FiBell, FiSearch, FiFilter, FiAlertCircle, 
    FiX, FiBarChart2, FiRefreshCw, FiChevronDown, FiChevronUp, FiDollarSign, FiPieChart 
} from 'react-icons/fi';
import { TbTrophy, TbBuilding, TbChartBar, TbFileDownload, TbClipboardList, TbHomeEdit } from 'react-icons/tb';
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, 
    ResponsiveContainer, Cell, PieChart, Pie 
} from 'recharts';
import PageTransition from '../components/PageTransition';

const AgencyDashboard = () => {
    const location = useLocation();
    const [activeTab, setActiveTab] = useState(location.state?.activeTab || 'home');

    useEffect(() => {
        if (location.state?.activeTab) {
            setActiveTab(location.state.activeTab);
        }
    }, [location.state?.activeTab]);

    const [projects, setProjects] = useState([]);
    const [aggregates, setAggregates] = useState({
        totalActiveAgencies: 0,
        totalMoaProjects: 0,
        totalTranche1Value: 0,
        pendingMoaTasks: 0
    });
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Context / Role State
    const userRole = localStorage.getItem('userRole');
    const userAgency = localStorage.getItem('userDivision'); // For Implementing Agency, division stores agency name
    const isAgencyUser = userRole === 'Implementing Agency';

    // Filters & Search
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedAgency, setSelectedAgency] = useState(isAgencyUser ? userAgency : 'All');

    // Grouping
    const [expandedAgencies, setExpandedAgencies] = useState({});

    // Liquidation Modal State
    const [selectedProjectForLiquidation, setSelectedProjectForLiquidation] = useState(null);

    useEffect(() => {
        fetchAgencyData();
    }, [selectedAgency]);

    const fetchAgencyData = async () => {
        try {
            setLoading(true);
            setError(null);

            // If agency user, we strictly filter by their agency in the API
            const params = new URLSearchParams();
            if (isAgencyUser) params.append('agency', userAgency);
            else if (selectedAgency !== 'All') params.append('agency', selectedAgency);

            const res = await fetch(`/api/agency-dashboard/projects?${params.toString()}`);
            if (!res.ok) throw new Error('Failed to fetch agency dashboard data');
            const data = await res.json();

            setAggregates(data.aggregates || {
                totalActiveAgencies: 0, totalMoaProjects: 0, totalTranche1Value: 0, pendingMoaTasks: 0
            });
            setProjects(data.projects || []);

            // Auto-expand if only one agency
            if (data.projects && data.projects.length > 0) {
                const uniqueAgencies = new Set(data.projects.map(p => p.implementing_agencies));
                if (uniqueAgencies.size === 1) {
                    setExpandedAgencies({ [Array.from(uniqueAgencies)[0]]: true });
                }
            }
        } catch (err) {
            console.error(err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    // Derived Data for Filters (Only for non-agency secondary filtering if needed)
    const agenciesList = useMemo(() => {
        const agencies = new Set(projects.map(p => p.implementing_agencies).filter(Boolean));
        return ['All', ...Array.from(agencies).sort()];
    }, [projects]);

    const filteredProjects = useMemo(() => {
        return projects.filter(project => {
            const matchesSearch =
                (project.project_name || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
                (project.moa || '').toLowerCase().includes(searchQuery.toLowerCase());
            return matchesSearch;
        });
    }, [projects, searchQuery]);

    const groupedProjects = useMemo(() => {
        const groups = {};
        filteredProjects.forEach(project => {
            const agency = project.implementing_agencies || 'Unknown Agency';
            if (!groups[agency]) {
                groups[agency] = [];
            }
            groups[agency].push(project);
        });
        return groups;
    }, [filteredProjects]);

    // Chart Data
    const statusChartData = useMemo(() => {
        const stats = {};
        projects.forEach(p => {
            const s = p.status || 'Not Started';
            stats[s] = (stats[s] || 0) + 1;
        });
        return Object.entries(stats).map(([name, value]) => ({ name, value }));
    }, [projects]);

    const trancheChartData = useMemo(() => {
        // Group by agency for comparison
        const agencyFunds = {};
        projects.forEach(p => {
            const agency = p.implementing_agencies || 'Other';
            if (!agencyFunds[agency]) agencyFunds[agency] = { name: agency, allocated: 0, liquidated: 0 };
            agencyFunds[agency].allocated += parseFloat(p.tranche_1 || 0);
            agencyFunds[agency].liquidated += (parseFloat(p.liquidated_tranche_1 || 0) + parseFloat(p.liquidated_tranche_2 || 0) + parseFloat(p.liquidated_tranche_3 || 0));
        });
        return Object.values(agencyFunds).sort((a, b) => b.allocated - a.allocated).slice(0, 5);
    }, [projects]);

    const COLORS = ['#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6'];

    const formatCurrency = (amount) => {
        if (amount == null) return 'Γé▒0.00';
        return new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP' }).format(amount);
    };



    const toggleGroup = (agency) => {
        setExpandedAgencies(prev => ({
            ...prev,
            [agency]: !prev[agency]
        }));
    };

    if (loading && projects.length === 0) {
        return (
            <div className="flex h-screen items-center justify-center bg-gray-50 dark:bg-slate-900">
                <div className="flex flex-col items-center">
                    <div className="h-16 w-16 animate-spin rounded-full border-t-4 border-b-4 border-blue-600"></div>
                    <p className="mt-4 text-lg font-bold text-slate-700 dark:text-slate-300 animate-pulse uppercase tracking-widest">Initialising Dashboard...</p>
                </div>
            </div>
        );
    }

    return (
        <PageTransition>
            <div className="min-h-screen bg-[#F8FAFC] dark:bg-slate-900 pb-24 font-sans selection:bg-blue-100">

                {/* PREMIUM HERO SECTION (Regional Office Style) */}
                <div className="bg-gradient-to-br from-[#004A99] to-[#002D5C] p-6 pb-20 rounded-b-[3rem] shadow-xl text-white relative z-[60]">

                    <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                        <div className="animate-in fade-in slide-in-from-left-4 duration-700">
                            <div className="flex items-center gap-3 mb-2">
                                <div className="p-2 bg-white/20 backdrop-blur-md rounded-lg">
                                    <TbBuilding className="text-white text-2xl" />
                                </div>
                                <h1 className="text-2xl sm:text-4xl font-black text-white tracking-tight drop-shadow-md">
                                    {isAgencyUser ? userAgency : 'Implementing Agency Dashboard'}
                                </h1>
                            </div>
                            <p className="text-blue-100 font-medium text-lg max-w-2xl">
                                {isAgencyUser 
                                    ? `Welcome, monitor your agency's project progress and fund utilization.` 
                                    : 'Centralized monitoring for external partner projects and MOA compliance.'}
                            </p>
                        </div>

                        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto animate-in fade-in slide-in-from-right-4 duration-700">
                            {!isAgencyUser && (
                                <div className="relative group">
                                    <FiFilter className="absolute left-4 top-1/2 -translate-y-1/2 text-white/60 group-hover:text-white transition-colors" />
                                    <select
                                        className="pl-12 pr-10 py-3 bg-white/10 hover:bg-white/20 backdrop-blur-md border border-white/20 text-white font-bold rounded-2xl outline-none appearance-none transition-all cursor-pointer min-w-[200px]"
                                        value={selectedAgency}
                                        onChange={(e) => setSelectedAgency(e.target.value)}
                                    >
                                        <option value="All" className="text-slate-800">All Agencies</option>
                                        {agenciesList.filter(a => a !== 'All').map(agency => (
                                            <option key={agency} value={agency} className="text-slate-800">{agency}</option>
                                        ))}
                                    </select>
                                    <FiChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-white/60" />
                                </div>
                            )}

                            <button 
                                onClick={fetchAgencyData}
                                className="p-3 bg-white/10 hover:bg-white/20 backdrop-blur-md border border-white/20 rounded-2xl text-white transition-all flex items-center justify-center gap-2"
                                title="Refresh Data"
                            >
                                <FiRefreshCw className={loading ? "animate-spin" : ""} />
                                <span className="sm:hidden font-bold uppercase text-xs tracking-widest">Refresh</span>
                            </button>
                        </div>
                    </div>
                </div>

                <div className="px-5 -mt-10 space-y-6 relative z-20">
                    {/* METRIC CARDS OVERLAP */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                        <MetricCard
                            title="Total Projects"
                            value={aggregates.totalMoaProjects}
                            icon={<TbClipboardList size={28} />}
                            color="blue"
                            delay={0}
                        />
                        <MetricCard
                            title="Active Agencies"
                            value={aggregates.totalActiveAgencies}
                            icon={<TbBuilding size={28} />}
                            color="purple"
                            delay={0.1}
                        />
                        <MetricCard
                            title="Total Tranche 1"
                            value={formatCurrency(aggregates.totalTranche1Value)}
                            icon={<FiDollarSign size={28} />}
                            color="emerald"
                            isCurrency
                            delay={0.2}
                        />
                        <MetricCard
                            title="Pending Tasks"
                            value={aggregates.pendingMoaTasks}
                            icon={<FiClock size={28} />}
                            color="amber"
                            delay={0.3}
                        />
                    </div>


                {/* ACTIVE TAB CONTENT */}
                {activeTab === 'home' && (
                    <>
                        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">

                        {/* CHARTS SECTION */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        {/* Project Status Distribution */}
                        <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] shadow-xl border border-slate-100 dark:border-slate-700">
                            <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                                <FiPieChart className="text-blue-500" /> Project Status Distribution
                            </h2>
                            <div className="h-[300px] w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={statusChartData}
                                            innerRadius={60}
                                            outerRadius={100}
                                            paddingAngle={5}
                                            dataKey="value"
                                        >
                                            {statusChartData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                            ))}
                                        </Pie>
                                        <Tooltip 
                                            contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                                        />
                                        <Legend />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Agency Fund Utilization */}
                        <div className="bg-white dark:bg-slate-800 p-6 rounded-[2rem] shadow-xl border border-slate-100 dark:border-slate-700">
                            <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2">
                                <FiBarChart2 className="text-emerald-500" /> Allocated vs Liquidated (Top 5)
                            </h2>
                            <div className="h-[300px] w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={trancheChartData} layout="vertical">
                                        <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} opacity={0.1} />
                                        <XAxis type="number" hide />
                                        <YAxis dataKey="name" type="category" width={100} tick={{ fontSize: 10, fontWeight: 'bold' }} />
                                        <Tooltip 
                                            formatter={(value) => formatCurrency(value)}
                                            contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                                        />
                                        <Legend />
                                        <Bar dataKey="allocated" name="Allocated" fill="#3B82F6" radius={[0, 4, 4, 0]} />
                                        <Bar dataKey="liquidated" name="Liquidated" fill="#10B981" radius={[0, 4, 4, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>

                    {/* PROJECT TABLE SECTION */}
                    <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl border border-slate-50 dark:border-slate-700 overflow-hidden">
                        <div className="p-8 border-b border-slate-100 dark:border-slate-700 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 bg-slate-50/50 dark:bg-slate-800/50">
                            <div>
                                <h2 className="text-2xl font-black text-slate-800 dark:text-white tracking-tight">Project Portfolio</h2>
                                <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mt-1">
                                    Monitoring {filteredProjects.length} Active Projects
                                </p>
                            </div>

                            <div className="relative w-full sm:w-80 group">
                                <FiSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                                <input
                                    type="text"
                                    placeholder="Search Project or MOA ID..."
                                    className="pl-12 pr-4 py-3 w-full bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl text-sm outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all shadow-sm"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead>
                                    <tr className="bg-slate-50 dark:bg-slate-800/50">
                                        <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest italic w-10"></th>
                                        <th className="px-6 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-widest">Project Particulars</th>
                                        <th className="px-6 py-5 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">Documents</th>
                                        <th className="px-6 py-5 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Financials</th>
                                        <th className="px-6 py-5 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                                        <th className="px-8 py-5 text-right text-[10px] font-black text-slate-400 uppercase tracking-widest">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                    {Object.entries(groupedProjects).map(([agency, projList]) => (
                                        <React.Fragment key={agency}>
                                            <tr 
                                                className="bg-slate-50/80 dark:bg-slate-900/40 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-900 transition-colors"
                                                onClick={() => toggleGroup(agency)}
                                            >
                                                <td className="px-8 py-4">
                                                    {expandedAgencies[agency] ? <FiChevronUp className="text-blue-500" /> : <FiChevronDown className="text-slate-400" />}
                                                </td>
                                                <td colSpan="5" className="px-6 py-4">
                                                    <div className="flex items-center gap-2">
                                                        <span className="font-black text-slate-700 dark:text-slate-200 uppercase tracking-wider">{agency}</span>
                                                        <span className="bg-blue-100 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 text-[10px] font-black px-2 py-0.5 rounded-full border border-blue-200 dark:border-blue-800/50">
                                                            {projList.length} PROJECTS
                                                        </span>
                                                    </div>
                                                </td>
                                            </tr>

                                            <AnimatePresence>
                                                {expandedAgencies[agency] && projList.map((project, pIdx) => (
                                                    <motion.tr
                                                        initial={{ opacity: 0, x: -10 }}
                                                        animate={{ opacity: 1, x: 0 }}
                                                        exit={{ opacity: 0, x: -10 }}
                                                        transition={{ delay: pIdx * 0.05 }}
                                                        key={project.project_id}
                                                        className="group hover:bg-blue-50/30 dark:hover:bg-blue-900/10 transition-colors"
                                                    >
                                                        <td className="px-8 py-6 w-10 border-l-4 border-transparent group-hover:border-blue-500 transition-all"></td>
                                                        <td className="px-6 py-6 border-transparent">
                                                            <div>
                                                                <h4 className="font-bold text-slate-800 dark:text-white leading-tight mb-1 group-hover:text-blue-600 transition-colors">
                                                                    {project.project_name || 'Project Unnamed'}
                                                                </h4>
                                                                <div className="flex flex-wrap gap-2">
                                                                    <span className="text-[10px] font-bold text-slate-400 uppercase font-mono bg-slate-100 dark:bg-slate-700 px-1.5 py-0.5 rounded">
                                                                        ID: {project.project_id}
                                                                    </span>
                                                                    <span className="text-[10px] font-bold text-blue-500 uppercase bg-blue-50 dark:bg-blue-900/30 px-1.5 py-0.5 rounded">
                                                                        {project.mode_of_project}
                                                                    </span>
                                                                </div>
                                                            </div>
                                                        </td>
                                                        <td className="px-6 py-6">
                                                            <div className="flex flex-col gap-1 items-center">
                                                                <div className={`text-[10px] font-black px-2 py-1 rounded-lg flex items-center gap-1 ${project.has_moa ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                                                                    {project.has_moa ? <FiCheckCircle /> : <FiAlertCircle />} MOA
                                                                </div>
                                                                <div className={`text-[10px] font-black px-2 py-1 rounded-lg flex items-center gap-1 ${project.has_rta ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                                                                    {project.has_rta ? <FiCheckCircle /> : <FiAlertCircle />} RTA
                                                                </div>
                                                            </div>
                                                        </td>
                                                        <td className="px-6 py-6 text-right">
                                                            <div className="flex flex-col">
                                                                <span className="text-xs font-black text-slate-400 uppercase tracking-tighter mb-1">Total Allocated</span>
                                                                <span className="text-lg font-black text-slate-800 dark:text-white leading-none mb-1">
                                                                    {formatCurrency(project.tranche_1)}
                                                                </span>
                                                                <div className="flex justify-end gap-1">
                                                                     <span className="text-[9px] font-bold text-emerald-500 bg-emerald-50 dark:bg-emerald-900/30 px-1.5 rounded">
                                                                        LIQ: {formatCurrency(parseFloat(project.liquidated_tranche_1 || 0) + parseFloat(project.liquidated_tranche_2 || 0) + parseFloat(project.liquidated_tranche_3 || 0))}
                                                                     </span>
                                                                </div>
                                                            </div>
                                                        </td>
                                                        <td className="px-6 py-6 text-center">
                                                            <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${
                                                                project.status === 'Completed' 
                                                                    ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-200' 
                                                                    : 'bg-blue-500 text-white shadow-lg shadow-blue-200'
                                                            }`}>
                                                                {project.status || 'Ongoing'}
                                                            </span>
                                                        </td>
                                                        <td className="px-8 py-6 text-right">
                                                            <button 
                                                                onClick={() => setSelectedProjectForLiquidation(project)}
                                                                className="p-3 bg-slate-100 dark:bg-slate-700 hover:bg-blue-600 hover:text-white rounded-2xl transition-all shadow-sm hover:shadow-lg hover:shadow-blue-200"
                                                                title="Manage Liquidation"
                                                            >
                                                                <TbChartBar size={20} />
                                                            </button>
                                                        </td>
                                                    </motion.tr>
                                                ))}
                                            </AnimatePresence>
                                        </React.Fragment>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                {/* MODAL */}
                <AnimatePresence>
                    {selectedProjectForLiquidation && (
                        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-md">
                            <motion.div
                                initial={{ scale: 0.9, opacity: 0, y: 20 }}
                                animate={{ scale: 1, opacity: 1, y: 0 }}
                                exit={{ scale: 0.9, opacity: 0, y: 20 }}
                                className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-2xl w-full max-w-lg overflow-hidden border border-white/20"
                            >
                                <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-8 text-white relative">
                                    <div className="absolute top-8 right-8 cursor-pointer hover:rotate-90 transition-transform" onClick={() => setSelectedProjectForLiquidation(null)}>
                                        <FiX size={24} />
                                    </div>
                                    <h3 className="text-2xl font-black tracking-tight mb-2">Fund Liquidation</h3>
                                    <p className="text-blue-100 font-bold text-sm uppercase tracking-widest opacity-80 truncate">
                                        {selectedProjectForLiquidation.project_name}
                                    </p>
                                </div>

                                <div className="p-10 space-y-6">
                                    <LiquidationEntry
                                        label="Tranche 1"
                                        initialValue={selectedProjectForLiquidation.liquidated_tranche_1}
                                        onUpdate={(val) => selectedProjectForLiquidation.liquidated_tranche_1 = val}
                                    />
                                    <LiquidationEntry
                                        label="Tranche 2"
                                        initialValue={selectedProjectForLiquidation.liquidated_tranche_2}
                                        onUpdate={(val) => selectedProjectForLiquidation.liquidated_tranche_2 = val}
                                    />
                                    <LiquidationEntry
                                        label="Tranche 3"
                                        initialValue={selectedProjectForLiquidation.liquidated_tranche_3}
                                        onUpdate={(val) => selectedProjectForLiquidation.liquidated_tranche_3 = val}
                                    />

                                    <div className="pt-6 flex gap-4">
                                        <button 
                                            onClick={() => setSelectedProjectForLiquidation(null)}
                                            className="flex-1 py-4 text-slate-400 font-black uppercase tracking-widest hover:text-slate-600 transition-colors"
                                        >
                                            Discard
                                        </button>
                                        <button 
                                            onClick={async () => {
                                                try {
                                                    const res = await fetch(`/api/agency-dashboard/projects/${selectedProjectForLiquidation.project_id}/liquidation`, {
                                                        method: 'PATCH',
                                                        headers: { 'Content-Type': 'application/json' },
                                                        body: JSON.stringify({
                                                            liquidated_tranche_1: selectedProjectForLiquidation.liquidated_tranche_1,
                                                            liquidated_tranche_2: selectedProjectForLiquidation.liquidated_tranche_2,
                                                            liquidated_tranche_3: selectedProjectForLiquidation.liquidated_tranche_3
                                                        })
                                                    });
                                                    if (res.ok) {
                                                        fetchAgencyData();
                                                        setSelectedProjectForLiquidation(null);
                                                    }
                                                } catch (e) { console.error(e); }
                                            }}
                                            className="flex-1 py-4 bg-blue-600 text-white font-black uppercase tracking-widest rounded-2xl shadow-xl shadow-blue-200 hover:bg-blue-700 transition-all transform hover:scale-105 active:scale-95"
                                        >
                                            Update
                                        </button>
                                    </div>
                                </div>
                            </motion.div>
                        </div>
                    )}
                </AnimatePresence>
                </>
                )}

                {activeTab === 'deployment' && (
                    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                        <div className="bg-white dark:bg-slate-800 p-12 rounded-[2rem] shadow-xl border border-slate-100 dark:border-slate-700 text-center flex flex-col items-center justify-center min-h-[400px]">
                            <TbClipboardList className="text-[100px] text-slate-200 dark:text-slate-700 mb-6" />
                            <h2 className="text-2xl font-black text-slate-800 dark:text-white mb-2 tracking-tight">Deployment Planner</h2>
